import WebSocket from 'ws';
import { config } from './config';

export interface DeepgramTtsOptions {
  apiKey?: string;
  model?: string;
}

/**
 * DeepgramTts
 * 
 * Manages streaming Text-to-Speech (TTS) using Deepgram's Aura WebSocket API (`/v1/speak`).
 * Operates on a per-agent-turn basis:
 * 1. Opens a WebSocket connection for the turn.
 * 2. Streams text sentences incrementally as they are generated by the LLM.
 * 3. Yields base64-encoded 16 kHz PCM chunks as they arrive for instant playback.
 * 4. Supports instantaneous abortion on user interruption (closing the socket halts generation and billing).
 */
export class DeepgramTts {
  private ws: WebSocket | null = null;
  private apiKey: string;
  private model: string;

  // Queue to buffer incoming audio chunks for the async generator
  private queue: string[] = [];
  private isFinal: boolean = false;
  private isClosed: boolean = false;
  private resolveNext: ((value: { chunk?: string; done: boolean }) => void) | null = null;

  constructor(options?: DeepgramTtsOptions) {
    this.apiKey = options?.apiKey || config.DEEPGRAM_API_KEY || '';
    // Use aura-asteria-en (warm, natural conversational voice) by default
    this.model = options?.model || 'aura-asteria-en';

    if (!this.apiKey) {
      throw new Error('DEEPGRAM_API_KEY is not set. Please add it to your .env file.');
    }
  }

  /**
   * Connects to Deepgram's streaming TTS WebSocket in the background.
   */
  public async start(): Promise<void> {
    if (this.ws) {
      return;
    }

    this.isClosed = false;
    this.isFinal = false;
    this.queue = [];

    // URL parameters:
    // model: Aura TTS voice model
    // encoding: linear16 (16-bit uncompressed PCM)
    // sample_rate: 16000 (16 kHz, matches our browser AudioPlayer pipeline)
    const url = `wss://api.deepgram.com/v1/speak?model=${encodeURIComponent(this.model)}&encoding=linear16&sample_rate=16000`;

    return new Promise<void>((resolve, reject) => {
      this.ws = new WebSocket(url, {
        headers: {
          Authorization: `Token ${this.apiKey}`,
        },
      });

      this.ws.on('open', () => {
        resolve();
      });

      this.ws.on('message', (data: WebSocket.RawData, isBinary: boolean) => {
        if (isBinary) {
          // Deepgram streams raw 16 kHz PCM binary audio chunks
          const buffer = Buffer.isBuffer(data) ? data : Buffer.from(data as ArrayBuffer);
          const base64Chunk = buffer.toString('base64');

          if (this.resolveNext) {
            const resolver = this.resolveNext;
            this.resolveNext = null;
            resolver({ chunk: base64Chunk, done: false });
          } else {
            this.queue.push(base64Chunk);
          }
        } else {
          // Deepgram sends JSON control messages, e.g. {"type": "Flushed"} or {"type": "Metadata"}
          try {
            const message = JSON.parse(data.toString());
            if (message.type === 'Flushed') {
              this.markDone();
            }
          } catch {
            // Ignore non-critical JSON parse errors
          }
        }
      });

      this.ws.on('error', (err: Error) => {
        if (!this.isClosed) {
          reject(err);
        }
      });

      this.ws.on('close', () => {
        this.markDone();
      });
    });
  }

  /**
   * Streams a text fragment or sentence to Deepgram.
   */
  public sendText(text: string): void {
    if (this.ws && this.ws.readyState === WebSocket.OPEN && text.trim().length > 0) {
      this.ws.send(JSON.stringify({ type: 'Speak', text: text.trim() + ' ' }));
    }
  }

  /**
   * Signals to Deepgram that all text for this turn has been sent.
   * Flushes any remaining buffered speech and schedules closing.
   */
  public finish(): void {
    if (this.ws && this.ws.readyState === WebSocket.OPEN) {
      // Force Deepgram to synthesize any remaining buffered text immediately
      this.ws.send(JSON.stringify({ type: 'Flush' }));
      // Tell Deepgram no more text is coming for this stream
      this.ws.send(JSON.stringify({ type: 'Close' }));
    }
  }

  /**
   * Terminates the connection immediately.
   * Calling this when the user interrupts stops active audio generation and halts billing on the provider side.
   */
  public close(): void {
    this.isClosed = true;
    if (this.ws) {
      try {
        this.ws.terminate();
      } catch {
        // Socket may already be closed
      }
      this.ws = null;
    }
    this.markDone();
  }

  /**
   * Marks the stream as finished and releases any waiting audio consumer.
   */
  private markDone(): void {
    this.isFinal = true;
    if (this.resolveNext) {
      const resolver = this.resolveNext;
      this.resolveNext = null;
      resolver({ done: true });
    }
  }

  /**
   * Async generator yielding base64-encoded 16 kHz PCM chunks as they arrive from Deepgram.
   */
  public async *audio(): AsyncGenerator<string, void, unknown> {
    while (true) {
      if (this.queue.length > 0) {
        yield this.queue.shift()!;
      } else if (this.isFinal || this.isClosed) {
        break;
      } else {
        const next = await new Promise<{ chunk?: string; done: boolean }>((resolve) => {
          this.resolveNext = resolve;
        });

        if (next.chunk) {
          yield next.chunk;
        }

        if (next.done) {
          break;
        }
      }
    }
  }
}

// Export DeepgramTts as the primary class
export default DeepgramTts;
